{"action":"created","comment":{"url":"https://api.github.com/repos/scipy/scipy/pulls/comments/1745813669","pull_request_review_id":2283506228,"id":1745813669,"node_id":"PRRC_kwDOABZIoc5oDwCl","diff_hunk":"@@ -261,10 +258,167 @@ namespace detail {
      * See ContinuedFractionSeriesGenerator for details.
