     }

+    /* Find initial bracket for a bracketing scalar root finder. A valid bracket is a pair of points a < b for
+     * which the signs of f(a) and f(b) differ. If f(x0) = 0, where x0 is the initial guess, this bracket finder
+     * will return the bracket (x0, x0). It is expected that the rootfinder will check if the bracket
+     * endpoints are roots.
+     *
+     * This is a private function intended specifically for the situation where
+     * the goal is to invert a CDF function F for a parametrized family of distributions with respect to one
+     * parameter, when the other parameters are known, and where F is monotonic with respect to the unknown parameter.
+     *
+     * Note that this takes a pointer to a function taking a tuple of args along with a scalar
+     * double argument. A tuple of args for specializing func is also passed as the final argument.
+     * It would be much cleaner to use std::function and capturing lambda's to specialize the
+     * function we are finding a root for, but I couldn't get this working in CuPy using NVRTC.
+     * This should be revisited in the future in order to allow simplifying this code. */
+    template <typename... Args>
+    XSF_HOST_DEVICE inline std::tuple<double, double, double, double, int> bracket_root_for_cdf_inversion(
+        double (*func)(double, std::tuple<Args...>), double x0, double xmin, double xmax, double step0_left,
+        double step0_right, double factor_left, double factor_right, bool increasing, std::uint64_t maxiter,
+        std::tuple<Args...> args
+    ) {
+        double y0 = func(x0, args);
+
+        if (y0 == 0) {
+            // Initial guess is correct.
+            std::tuple<double, double, double, double, int> result(x0, x0, y0, y0, 0);
+            return result;
+        }
+
+        double y0_sgn = std::signbit(y0);
+
+        bool search_left;
+        /* The frontier is the new leading endpoint of the expanding bracket. The
+         * interior endpoint trails behind the frontier. In each step, the old frontier
+         * endpoint becomes the new interior endpoint. */
+        double interior, frontier, y_interior, y_frontier, y_interior_sgn, y_frontier_sgn, boundary, factor;
+        if ((increasing && y0 < 0) || (!increasing && y0 > 0)) {
+            /* If func is increasing  and func(x_right) < 0 or if func is decreasing and
+             *  f(y_right) > 0, we should expand the bracket to the right. */
+            interior = x0, y_interior = y0;
+            frontier = x0 + step0_right;
+            y_interior_sgn = y0_sgn;
+            search_left = false;
+            boundary = xmax;
+            factor = factor_right;
+        } else {
+            /* Otherwise we move and expand the bracket to the left. */
+            interior = x0, y_interior = y0;
+            frontier = x0 + step0_left;
+            y_interior_sgn = y0_sgn;
+            search_left = true;
+            boundary = xmin;
+            factor = factor_left;
+        }
+
+        bool reached_boundary = false;
+        for (std::uint64_t i = 0; i < maxiter; i++) {
+            y_frontier = func(frontier, args);
+            y_frontier_sgn = std::signbit(y_frontier);
+            if (y_frontier_sgn != y_interior_sgn || (y_frontier == 0.0)) {
+                /* Stopping condition, func evaluated at endpoints of bracket has opposing signs,
+                 * meeting requirement for bracketing root finder. (Or endpoint has reached a
+                 * zero.) */
+                if (search_left) {
+                    /* Ensure we return an interval (a, b) with a < b. */
+                    std::swap(interior, frontier);
+                    std::swap(y_interior, y_frontier);
+                }
+                std::tuple<double, double, double, double, int> result(interior, frontier, y_interior, y_frontier, 0);
+                return result;
+            }
+            if (reached_boundary) {
+                /* We've reached a boundary point without finding a root . */
+                std::tuple<double, double, double, double, int> result(
+                    std::numeric_limits<double>::quiet_NaN(), std::numeric_limits<double>::quiet_NaN(),
+                    std::numeric_limits<double>::quiet_NaN(), std::numeric_limits<double>::quiet_NaN(),
+                    search_left ? 1 : 2
+                );
+                return result;
+            }
+            double step = (frontier - interior) * factor;
+            interior = frontier;
+            y_interior = y_frontier;
+            y_interior_sgn = y_frontier_sgn;
+            frontier += step;
+            if ((search_left && frontier <= boundary) || (!search_left && frontier >= boundary)) {
+                /* If the frontier has reached the boundary, set a flag so the algorithm will know
+                 * not to search beyond this point. */
+                frontier = boundary;
+                reached_boundary = true;
+            }
+        }
+        /* Failed to converge within maxiter iterations. If maxiter is sufficiently high and
+         * factor_left and factor_right are set appropriately, this should only happen due to
+         * a bug in this function. Limiting the number of iterations is a defensive programming measure. */
+        std::tuple<double, double, double, double, int> result(
+            std::numeric_limits<double>::quiet_NaN(), std::numeric_limits<double>::quiet_NaN(),
+            std::numeric_limits<double>::quiet_NaN(), std::numeric_limits<double>::quiet_NaN(), 3
+        );
+        return result;","path":"scipy/special/xsf/tools.h","commit_id":"7ae91e21ad421fc3e82e47e010e000ae9e59bad8","original_commit_id":"7ae91e21ad421fc3e82e47e010e000ae9e59bad8","user":{"login":"izaid","id":482179,"node_id":"MDQ6VXNlcjQ4MjE3OQ==","avatar_url":"https://avatars.githubusercontent.com/u/482179?v=4","gravatar_id":"","url":"https://api.github.com/users/izaid","html_url":"https://github.com/izaid","followers_url":"https://api.github.com/users/izaid/followers","following_url":"https://api.github.com/users/izaid/following{/other_user}","gists_url":"https://api.github.com/users/izaid/gists{/gist_id}","starred_url":"https://api.github.com/users/izaid/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/izaid/subscriptions","organizations_url":"https://api.github.com/users/izaid/orgs","repos_url":"https://api.github.com/users/izaid/repos","events_url":"https://api.github.com/users/izaid/events{/privacy}","received_events_url":"https://api.github.com/users/izaid/received_events","type":"User","site_admin":false},"body":"Same as comment as above with just `{...}`.","created_at":"2024-09-05T16:02:47Z","updated_at":"2024-09-05T16:02:48Z","html_url":"https://github.com/scipy/scipy/pull/21454#discussion_r1745813669","pull_request_url":"https://api.github.com/repos/scipy/scipy/pulls/21454","author_association":"CONTRIBUTOR","_links":{"self":{"href":"https://api.github.com/repos/scipy/scipy/pulls/comments/1745813669"},"html":{"href":"https://github.com/scipy/scipy/pull/21454#discussion_r1745813669"},"pull_request":{"href":"https://api.github.com/repos/scipy/scipy/pulls/21454"}},"reactions":{"url":"https://api.github.com/repos/scipy/scipy/pulls/comments/1745813669/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":null,"original_start_line":null,"start_side":null,"line":363,"original_line":363,"side":"RIGHT","original_position":178,"position":178,"subject_type":"line"},"pull_reques