+            qkm2 = 1.0;
+            pkm1 = x;
+            qkm1 = *n + *n;
+            xk = -x * x;
+            yk = qkm1;
+            ans = 0.0; /* ans=0.0 ensures that t=1.0 in the first iteration */
+            ctr = 0;
+            do {
+                yk += 2.0;
+                pk = pkm1 * yk + pkm2 * xk;
+                qk = qkm1 * yk + qkm2 * xk;
+                pkm2 = pkm1;
+                pkm1 = pk;
+                qkm2 = qkm1;
+                qkm1 = qk;
+
+                /* check convergence */
+                if (qk != 0 && ctr > miniter)
+                    r = pk / qk;
+                else
+                    r = 0.0;
+
+                if (r != 0) {
+                    t = std::abs((ans - r) / r);
+                    ans = r;
+                } else {
+                    t = 1.0;
+                }
+
+                if (++ctr > maxiter) {
+                    set_error("jv", SF_ERROR_UNDERFLOW, NULL);
