+                ans = 1.0;
+
+            /* Change n to n-1 if n < 0 and the continued fraction is small */
+            if (nflag > 0) {
+                if (std::abs(ans) < 0.125) {
+                    nflag = -1;
+                    *n = *n - 1.0;
+                    goto fstart;
+                }
+            }
+
+            kf = *newn;
+
+            /* backward recurrence
+             *              2k
+             *  J   (x)  =  --- J (x)  -  J   (x)
+             *   k-1         x   k         k+1
+             */
+
+            pk = 1.0;
+            pkm1 = 1.0 / ans;
+            k = *n - 1.0;
